/**
 * Situations: the list of conversations, the briefing with its two dials, the
 * conversation itself, the break in time, the debrief, and the English a
 * scene holds that the learner reads (titles, places, role cards, objectives,
 * stage directions, how a run ended, the curveballs, the errands).
 *
 * Every scene line here is translated at the point of display only. The
 * English in `lib/scenes/` is what the composing model is briefed with and
 * what the tests read, so it never changes; see `lib/scenes/onScreen.ts`.
 * No Estonian in here (ADR-005).
 */
